set -eu; umask 077; mc alias set local https://node4:9000 "$MINIO_ROOT_USER" "$MINIO_ROOT_PASSWORD" --api S3v4 --path on; mc mb --ignore-existing local/thanos-metrics; cat > /tmp/thanos-metrics-policy.json <<'POLICY_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "s3:ListBucket",
        "s3:GetBucketLocation",
        "s3:ListBucketMultipartUploads"
      ],
      "Resource": ["arn:aws:s3:::thanos-metrics"]
    },
    {
      "Effect": "Allow",
      "Action": [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:AbortMultipartUpload",
        "s3:ListMultipartUploadParts"
      ],
      "Resource": ["arn:aws:s3:::thanos-metrics/*"]
    }
  ]
}
POLICY_EOF
mc admin policy create local thanos-metrics /tmp/thanos-metrics-policy.json 2>/dev/null || true; mc admin user add local "$S3_ACCESS_KEY" "$S3_SECRET_KEY" 2>/dev/null || true; mc admin policy attach local thanos-metrics --user "$S3_ACCESS_KEY"; rm -f /tmp/thanos-metrics-policy.json; mc ls local

